# Generated by build.py from recipe.yml for recipe surl-run-a-test-server-in-ci. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/greeting.txt'), "Welcome aboard.`n")
[IO.File]::WriteAllText((Join-Path $PWD 'ci-servers.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# A CI step: start surl's HTTP and SMTP listeners, write their URLs to servers.env, run the`n# tests with those URLs in the environment, then stop surl. The step fails with surl's exit`n# code if surl does not start or ends before it is stopped, and with the tests' if they fail.`n# Usage: sh ci-servers.sh <http port> <smtp port> <test command> [<argument>...]`nhttp_port=`$1; smtp_port=`$2; shift 2`n: > listening.txt`nsurl -v --directory site --mail-domain example.com --mailbox app@example.com:secret \`n  `"http://127.0.0.1:`$http_port/`" `"smtp://127.0.0.1:`$smtp_port/`" > listening.txt 2> surl.log &`npid=`$!`necho `"`$pid`" > surl.pid`n`n# One Listening on line per listen URL once both have bound. If surl exits first, it`n# refused to start: show why and fail the step with its exit code.`ntries=0`nuntil [ `"`$(grep -c '^Listening on ' listening.txt)`" -eq 2 ]; do`n  if ! kill -0 `"`$pid`" 2>/dev/null; then`n    wait `"`$pid`"; code=`$?`n    cat surl.log >&2`n    echo `"surl did not start: exit `$code`" >&2`n    exit `"`$code`"`n  fi`n  tries=`$((tries + 1))`n  if [ `"`$tries`" -ge 100 ]; then kill `"`$pid`"; echo `"surl did not start in 10 s`" >&2; exit 1; fi`n  sleep 0.1`ndone`n`n# The URLs, as NAME=value lines a later step can read too.`nsed -n -e 's|^Listening on \(http://.*\)|HTTP_URL=\1|p' \`n       -e 's|^Listening on \(smtp://.*\)|SMTP_URL=\1|p' listening.txt > servers.env`n. ./servers.env`nexport HTTP_URL SMTP_URL`n`n`"`$@`"`ntests=`$?`n`n# Stop surl and read how it ended: 0 when it handled SIGTERM, 143 when the shell ended it`n# outright (Git Bash on Windows). Any other code means it ended before it was asked to.`nkill `"`$pid`" 2>/dev/null`nwait `"`$pid`"; code=`$?`necho `"tests: exit `$tests; surl: exit `$code`" >&2`ncase `$code in`n  0|143) ;;`n  *) echo `"surl ended before it was stopped`" >&2`n     [ `"`$tests`" -ne 0 ] || tests=`$code ;;`nesac`nexit `"`$tests`"`n")
[IO.File]::WriteAllText((Join-Path $PWD 'tests.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# The job's tests: fetch the greeting over HTTP and mail it over SMTP, to the URLs the step`n# put in the environment. The first failure ends them with curl's exit code.`n# Usage: sh tests.sh [<mailbox password>]`nset -e`ngreeting=`$(curl -fsS `"`${HTTP_URL}greeting.txt`")`nprintf 'Subject: Greeting\r\n\r\n%s\r\n' `"`$greeting`" |`n  curl -sS -u `"app@example.com:`${1:-secret}`" --mail-from app@example.com \`n    --mail-rcpt app@example.com -T - `"`${SMTP_URL}example.com`"`necho `"mailed: `$greeting`"`n")
[IO.File]::WriteAllText((Join-Path $PWD 'kill-surl.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Stands in for a test that brings the server down: ends surl at once with SIGKILL.`nkill -9 `"`$(cat surl.pid)`"`n")
$server0 = Start-Process surl -ArgumentList 'http://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { sh ci-servers.sh 0 0 sh tests.sh } finally { Stop-Process $server0 }
